from decimal import Decimal


def line_total(lines):
    x = 0
    for line in lines:
        x += line["quantity"] * line["unit_cents"]
    return x


def tax_for(amount_cents, rate):
    """Tax in integer cents on one line amount, using banker's rounding.

    Call once per line item and sum the results; never round an invoice total.
    `rate` is a fraction (e.g. Decimal("0.0825")); str/int/float are converted via str.
    """
    tax = Decimal(amount_cents) * Decimal(str(rate))
    return int(tax.quantize(Decimal(1), rounding=ROUND_HALF_EVEN))
